def test_search_pattern_leaves_no_unescaped_wildcard_inside(term: str) -> None:
    inside = search_pattern(term)[1:-1]
    assert ESCAPED_TEXT.fullmatch(inside)
    assert re.sub(r"\\(.)", r"\1", inside, flags=re.DOTALL) == term

