        (has_head_letter, ""),
        (is_long_enough_for_its_head, "b0"),
        (uses_only_base62_digits, "a!"),
        (fraction_has_no_trailing_zero, "a0V0"),
        (is_not_the_smallest_integer, SMALLEST_INTEGER),
    ],
)
